#include <bits/stdc++.h>

using namespace std;

string a, c;
int b, d, dp[128], ans, cnt;

int main() {
    cin >> b >> d >> a >> c;

    for (int i = 0; i < (int)c.size(); i++) {
        cnt = 0;
        for (int j = 0; j < (int)a.size(); j++) {
            if (c[cnt] == a[j]) {
                dp[i]++;
                cnt = (cnt + 1) % c.size();
            }
        }
        c = c.substr(1) + c[0];
    }

    cnt = 0;
    for (int i = 0; i < b; i++) {
        ans += dp[cnt];
        cnt = (cnt + dp[cnt]) % c.size();
    }

    cout << (ans / d) / c.size();
    return 0;
}

